/*
 * 向 javadoc 页面注入站点图标。
 * ico 以 base64 内嵌，避免额外向产物目录拷贝文件；
 * 图标源文件为 javadoc/favicon.ico，更换时重新编码此串即可。
 */
(function () {
    var link = document.createElement('link');
    link.rel = 'icon';
    link.type = 'image/x-icon';
    link.href = 'data:image/x-icon;base64,';
    document.head.appendChild(link);
})();
